/****************************************************************************
 * app/velaguard/vg_net_policy.h
 *
 * Pure failover policy. No NuttX, POSIX, or ESP types.
 * Host tests compile this file with gcc.
 ****************************************************************************/

#ifndef __VELAGUARD_VG_NET_POLICY_H
#define __VELAGUARD_VG_NET_POLICY_H

#include <stdbool.h>
#include <stdint.h>

/** 连续 ping 失败达到该次数才判 RJ45 不健康。 */
#define VG_NET_PING_FAIL_N       3
/** 从 Wi-Fi 抢回 RJ45 前，RJ45 需持续健康的窗口（毫秒）。 */
#define VG_NET_RJ45_HOLD_MS      10000u
/** 退避基数：1s，每次指数 ×2。 */
#define VG_NET_BACKOFF_BASE_MS   1000u
/** 退避上限：60s。 */
#define VG_NET_BACKOFF_MAX_MS    60000u
/** Wi-Fi join 连续失败达到该次数时请求 ESP 软复位。 */
#define VG_NET_ESP_RESET_TRIES   5
/** RJ45 稳定在线达到该时长后重置退避指数。 */
#define VG_NET_STABLE_RESET_MS   (5u * 60u * 1000u)

/**
 * @brief 策略层对外状态机（供日志 / vgnet status）。
 * @note VG_NET_DEGRADED 预留；当前实现主要用 DOWN / ONLINE_*。
 */
typedef enum
{
  VG_NET_DOWN = 0,
  VG_NET_CONNECTING,
  VG_NET_ONLINE_RJ45,
  VG_NET_ONLINE_WIFI,
  VG_NET_DEGRADED
} vg_net_state_t;

/**
 * @brief 活动业务出口（同时只应有一条）。
 */
typedef enum
{
  VG_EGRESS_NONE = 0,
  VG_EGRESS_RJ45,
  VG_EGRESS_WIFI
} vg_egress_t;

/**
 * @brief TCP 传输后端，与 active_egress 一一对应。
 * @note rj45 → posix（内核 eth0）；wifi → lesp（ESP AT 套接字）；none → 无 TCP。
 */
typedef enum
{
  VG_TCP_NONE = 0,
  VG_TCP_POSIX,
  VG_TCP_LESP
} vg_tcp_backend_t;

/**
 * @brief 测试注入：覆盖真实采样，便于无拔线验收。
 */
typedef enum
{
  VG_INJECT_AUTO = 0,
  VG_INJECT_FORCE_DOWN,
  VG_INJECT_FORCE_UP
} vg_inject_t;

/**
 * @brief 一拍采样输入（由 vg_net_mgr 填充后交给 step）。
 *
 * @note rj45_ping_sampled 为 false 时不得累加失败 streak，
 *       否则退避窗口内的空转会提前判挂。
 */
struct vg_net_sample
{
  bool rj45_link;
  bool rj45_has_ip;
  bool rj45_ping_ok;
  bool rj45_ping_sampled;
  bool wifi_assoc;
  bool wifi_has_ip;
};

/**
 * @brief 策略状态与输出标志。
 *
 * 调用方每拍读：
 * - active_egress / tcp_backend：该走哪条 TCP
 * - tcp_reconnect：本拍是否发生出口切换（须关旧开新）
 * - request_esp_reset：是否该软复位 ESP（由 note_wifi_join 置位）
 * - next_rj45_probe_ms / next_wifi_join_ms：下次动作时间
 */
struct vg_net_policy
{
  vg_net_state_t     state;
  vg_egress_t        active_egress;
  vg_tcp_backend_t   tcp_backend;
  bool               tcp_reconnect;
  bool               request_esp_reset;
  vg_inject_t        inject_rj45;
  vg_inject_t        inject_wifi;
  int                jitter_pct;
  unsigned           rj45_ping_fail_streak;
  unsigned           wifi_fail_streak;
  unsigned           rj45_backoff_exp;
  unsigned           wifi_backoff_exp;
  uint64_t           rj45_healthy_since_ms;
  uint64_t           next_rj45_probe_ms;
  uint64_t           next_wifi_join_ms;
  uint64_t           online_since_ms;
  bool               prev_rj45_link;
  bool               initialized;
};

/**
 * @brief 清零并标记策略已初始化。
 * @param p 策略对象。
 */
void vg_net_policy_init(struct vg_net_policy *p);

/**
 * @brief 根据本拍采样推进故障转移策略。
 *
 * @note 规则摘要：
 *       - RJ45 健康 = link ∧ DHCP ∧（连续 ping 失败 < 3）
 *       - RJ45 挂且 Wi-Fi 可用 → egress=wifi、backend=lesp
 *       - 从 wifi 抢回 rj45 需连续健康满 VG_NET_RJ45_HOLD_MS
 *       - 出口变化时 tcp_reconnect=true；调用方负责关旧 TCP 再开新
 *       - 仅在真实 ping 采样失败时调度退避；等待 tick 不得拉长探测周期
 *
 * @param p       策略对象（输入/输出）。
 * @param now_ms  单调时钟毫秒。
 * @param sample  本拍采样；不可为 NULL。
 */
void vg_net_policy_step(struct vg_net_policy *p,
                        uint64_t now_ms,
                        const struct vg_net_sample *sample);

/**
 * @brief 记录一次 Wi-Fi join 结果，并在失败达阈值时请求软复位。
 *
 * @param p   策略对象。
 * @param ok  true=join 成功；false=失败（累加 streak）。
 */
void vg_net_policy_note_wifi_join(struct vg_net_policy *p, bool ok);

/**
 * @brief 计算指数退避毫秒数：base×2^exp，封顶 VG_NET_BACKOFF_MAX_MS。
 *
 * @note jitter_pct 预留；主机单测传 0。当前实现故意忽略 RNG，避免纯策略层依赖随机源。
 *
 * @param exp         退避指数（0 → 1s，1 → 2s，…）。
 * @param jitter_pct  计划抖动百分比（未实现）。
 * @retval 退避等待毫秒数。
 */
uint32_t vg_net_policy_backoff_ms(unsigned exp, int jitter_pct);

/**
 * @brief 状态枚举转日志字符串。
 */
const char *vg_net_state_str(vg_net_state_t s);

/**
 * @brief 出口枚举转日志字符串（rj45|wifi|none）。
 */
const char *vg_egress_str(vg_egress_t e);

/**
 * @brief TCP 后端枚举转日志字符串（posix|lesp|none）。
 */
const char *vg_tcp_backend_str(vg_tcp_backend_t b);

#endif /* __VELAGUARD_VG_NET_POLICY_H */

/****************************************************************************
 * app/velaguard/vg_eth.h
 *
 * RJ45（eth0）采样与 icmp_ping。ping 只作故障判定，不会故障转移到 ESP。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_ETH_H
#define __VELAGUARD_VG_ETH_H

#include <nuttx/compiler.h>
#include <stdbool.h>
#include <arpa/inet.h>

/**
 * @brief eth0 一拍采样结果。
 */
struct vg_eth_sample
{
  bool link;                         /**< IFF_RUNNING */
  bool has_ip;                       /**< DHCP/静态 IPv4 非 0 */
  bool ping_ok;                      /**< 本拍或缓存的最近一次 ping */
  char ip[INET_ADDRSTRLEN];
  char gw[INET_ADDRSTRLEN];          /**< DHCP 网关；空则可用 Kconfig 兜底 */
};

/**
 * @brief 对 host 发 1 次 ICMP echo（绑定 eth0，若启用 BINDTODEVICE）。
 *
 * @param host 点分 IP 或主机名；NULL/空串返回 false。
 * @retval true  收到至少 1 个 reply。
 * @retval false 超时或失败。
 */
bool vg_eth_ping(FAR const char *host);

/**
 * @brief 采样 link / IP / 网关；可选执行 ping。
 *
 * @param out      输出；不可为 NULL。
 * @param do_ping  true 时在有 link+IP 时 ping 网关（或 VG_NET_PING_HOST）。
 * @note do_ping=false 时 ping_ok 复用上次成功缓存，避免空转把失败 streak 打满。
 */
void vg_eth_sample(struct vg_eth_sample *out, bool do_ping);

#endif

/****************************************************************************
 * app/velaguard/vg_esp_bearer.h
 *
 * ESP-01S（USART2 /dev/ttyS1）热备：上电 join，与 RJ45 是否健康无关。
 * TCP 仅在策略选中 wifi 时才走 lesp_*。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_ESP_BEARER_H
#define __VELAGUARD_VG_ESP_BEARER_H

#include <nuttx/compiler.h>
#include <arpa/inet.h>
#include <stdbool.h>

/**
 * @brief ESP 关联与 IP 采样结果。
 * @note 本树 lesp_ap_is_connected() 无实现；assoc 由 STA IP 是否非 0 推断。
 */
struct vg_esp_sample
{
  bool assoc;
  bool has_ip;
  char ip[INET_ADDRSTRLEN];
};

/**
 * @brief 若凭据为空，填入 Kconfig 默认 SSID/PSK。
 */
void vg_esp_cred_init(void);

/**
 * @brief 获取 AT UART 互斥锁（lesp 与 sample/status 共享）。
 */
void vg_esp_at_lock(void);

/**
 * @brief 释放 AT UART 互斥锁。
 */
void vg_esp_at_unlock(void);

/**
 * @brief net_mgr 是否已占用 ESP UART。
 * @note vgesp 在 busy 时应拒绝，避免与 lesp worker 抢 /dev/ttyS1。
 * @retval true  已 initialize，UART 归 net_mgr。
 * @retval false 空闲（或未开 VG_NET_FAILOVER）。
 */
bool vg_esp_uart_busy(void);

/**
 * @brief 覆盖 RAM 中的 Wi-Fi 凭据。
 *
 * @param ssid 非空 SSID。
 * @param psk  密码（可为空串，视 AP 而定）。
 * @retval 0        成功。
 * @retval -EINVAL  参数非法。
 */
int vg_esp_set_wifi(FAR const char *ssid, FAR const char *psk);

/**
 * @brief lesp_initialize；成功后标记 UART busy。
 * @retval 0  成功或已初始化。
 * @retval 负值 失败。
 */
int vg_esp_init(void);

/**
 * @brief 用当前凭据 lesp_ap_connect（热备 join）。
 * @retval 0  成功。
 * @retval 负值 失败。
 */
int vg_esp_join(void);

/**
 * @brief ESP 软复位（AT+RST 路径）；未 init 时先 init。
 * @retval 0  成功。
 * @retval 负值 失败。
 */
int vg_esp_soft_reset(void);

/**
 * @brief 采样关联与 STA IP。
 * @param out 输出；不可为 NULL。
 */
void vg_esp_sample(struct vg_esp_sample *out);

/**
 * @brief 当前 SSID（只读指针，指向内部静态缓冲）。
 */
FAR const char *vg_esp_ssid(void);

#endif

